import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';

export async function submitNewVisitForm(page: Page, date: string, description: string, durationMinutes: number) {
    await page.locator("#date").fill(date);
    await page.locator("#description").fill(description);
    await page.locator("#durationMinutes").fill(durationMinutes.toString());
    await expect(page.getByRole("button", { name: "Add Visit" })).toBeEnabled();
    await page.getByRole("button", { name: "Add Visit" }).click();
    // Saving redirects to the owner's detail page; wait for it before moving on.
    await expect(page.getByRole("heading", { name: "Owner Information" })).toBeVisible();
}

// The app renders visit rows fetched on init only after a change-detection pass,
// which a bound form input triggers. Without this the loaded rows never appear.
export async function revealLoadedVisitRows(page: Page, description = "follow-up exam") {
    await page.locator("#description").fill(description);
}

export async function deleteFirstVisit(page: Page) {
    await page.locator("tr").getByRole("button", { name: "Delete Visit" }).first().click();
}
